try {
    const name = await fetchAndPickFirst(userId);
    if (name) cachedExports.push(`${name}:${filter}`);
    return buildExportUrl(filter);
} catch (err) {
    error.value = err instanceof Error ? err.message : "导出失败";
    throw err;
} finally {
    exporting.value = false;
}

